const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const pretty=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const modules=[['Dashboard','⌂'],['Today','▣'],['Brain Dump','♧'],['Halloween Countdown','◉'],['Task Planner','☷'],['Costume Planner','♙'],['Shopping List','♧'],['Decorations','✦'],['Party Planner','♧'],['Trick or Treat','♧'],['Budget','▤'],['Meal & Treats','◕'],['Movie Nights','▣'],['Self-Care','♡'],['Focus Tools','◴'],['Overwhelmed Mode','♧'],['October Calendar','▦'],['After Halloween','❀']];
const recordModules=['Task Planner','Brain Dump','Costume Planner','Shopping List','Decorations','Party Planner','Trick or Treat','Budget','Meal & Treats','Movie Nights','Self-Care','After Halloween','Spooky Dopamine Menu'];
const hints={'Task Planner':'Choose one small next step. Give it a date when you need it.','Brain Dump':'Get the thought out of your head. You can organize it later.','Costume Planner':'Plan the look, the pieces and the fitting - one costume at a time.','Shopping List':'Keep quantities, shops and costs together.','Decorations':'A room, a corner or one pumpkin. Your version counts.','Party Planner':'Keep guests, places and preparations in one place.','Trick or Treat':'Plan your route, candy and timing before you head out.','Budget':'Track planned and actual costs in your chosen currency.','Meal & Treats':'Recipes, ingredients and preparation notes for your spooky table.','Movie Nights':'Build your watchlist, choose a night and bring the snacks.','Self-Care':'Make space for rest, a check-in or something you enjoy.','After Halloween':'Keep the good memories. Make next year a little easier.','Spooky Dopamine Menu':'Small seasonal pick-me-ups. Edit these suggestions to make them yours.'};
const defaults=()=>({app:'aurely-halloween',version:1,name:'Spooky Friend',currency:'USD',records:[],days:{},theme:{main:'#ff873e',accent:'#b992d8',bg:'#100e11',body:'Inter',heading:'Lora',hand:'Caveat',coverage:'accents',night:false,calm:false},timer:{remaining:300,end:null},suggestions:['Watch a Halloween movie','Make a Halloween drink','Decorate a small space','Listen to spooky playlist','5-minute tidy']});

function icon(name,cls=''){const paths={bell:'<path d="M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9Z"/><path d="M10 21h4"/>',home:'<path d="m3 10 9-7 9 7M6 9v12h5v-7h3v7h4V9"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v5m8-5v5M4 11h16M8 15h2m4 0h2m-8 3h2"/>',note:'<path d="M5 3h10l4 4v14H5zM14 3v6h5M8 13h8m-8 4h6"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',bag:'<path d="M5 8h14l2 13H3zM8 9V6a4 4 0 0 1 8 0v3"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M9 2h6m-3 3v8l3 2M18 6l2-2"/>',check:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 12 3 3 7-8"/>',heart:'<path d="M12 21 3 12C-2 3 9 0 12 7c3-7 14-4 9 5Z"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14q4 5 8 0M8 8h1m6 0h1"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4m-2-2h4"/>',moon:'<path d="M20 16A10 10 0 0 1 8 3a10 10 0 1 0 12 13Z"/>',battery:'<rect x="2" y="6" width="18" height="12" rx="2"/><path d="M22 10v4"/>',gift:'<path d="M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C1 8 7-3 12 8c5-11 11 0 0 0"/>',ghost:'<path d="M4 21V10a8 8 0 0 1 16 0v11l-4-3-4 3-4-3Z"/><path d="M9 10v2m6-2v2"/>',movie:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m10 8 6 4-6 4ZM3 8h3M3 16h3m12-8h3m-3 8h3"/>',cup:'<path d="M4 8h13v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM17 9h2a3 3 0 0 1 0 6h-2M7 3v2m4-3v3m4-2v2"/>'};return `<svg class="line-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.ghost}</svg>`;}
const navIcons=['home','calendar','ghost','timer','list','bag','bag','spark','gift','ghost','note','cup','movie','heart','timer','ghost','calendar','spark'];
function ghostArt(){return '<svg class="ghost-art" viewBox="0 0 50 54" aria-hidden="true"><path d="M8 43C5 37 10 31 11 24C9 0 40-1 39 24c0 8 8 15 6 21s-10-1-14 4-9-3-13-2-12 2-10-4Z" fill="#ffe7d1"/><ellipse cx="21" cy="23" rx="3" ry="5" fill="#241b20"/><ellipse cx="31" cy="22" rx="3" ry="5" fill="#241b20"/></svg>';}
function batArt(){return '<svg viewBox="0 0 60 28" aria-hidden="true"><path fill="currentColor" d="M0 2q11 12 19 6l7 5 1-8 4 4 4-4 1 8 7-5q8 6 17-6L52 22q-6-8-12-3l-10 9-10-9q-6-5-12 3Z"/></svg>';}

const KEY='aurely-halloween-demo-v1';
function validDate(value){if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T12:00:00');return !Number.isNaN(d.getTime())&&localDate(d)===value;}
function merge(raw){const d=defaults();if(!raw||typeof raw!=='object'||Array.isArray(raw)||!Array.isArray(raw.records)||raw.app!==d.app||raw.version!==1)throw Error('Invalid planner');
 const merged={...d,...raw,theme:{...d.theme,...raw.theme},timer:{...d.timer,...raw.timer}};
 const ids=new Set();merged.records=raw.records.map(r=>{if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||typeof r.title!=='string'||!recordModules.includes(r.module)||!validDate(r.date))throw Error('Invalid record');ids.add(r.id);const result={...r,detail:typeof r.detail==='string'?r.detail:'',notes:typeof r.notes==='string'?r.notes:'',done:!!r.done};if(r.module==='Budget'){for(const key of ['planned','actual']){const n=Number(r[key]??0);if(!Number.isFinite(n)||n<0||n>999999999.99)throw Error('Invalid amount');result[key]=Math.round(n*100)/100;}result.category=budgetCategories.includes(r.category)?r.category:'Other';}return result;});
 if(raw.days!==undefined&&(!raw.days||typeof raw.days!=='object'||Array.isArray(raw.days)))throw Error('Invalid days');merged.days={};for(const [date,value] of Object.entries(raw.days||{})){if(!validDate(date)||!value||typeof value!=='object'||(value.priorities!==undefined&&!Array.isArray(value.priorities)))throw Error('Invalid day');merged.days[date]={...value,priorities:[...new Set(value.priorities||[])].filter(id=>ids.has(id)).slice(0,3),energy:['Low Energy','Normal','Locked In'].includes(value.energy)?value.energy:'Normal',mood:typeof value.mood==='string'?value.mood:''};}
 for(const key of ['main','accent','bg'])if(!/^#[\da-f]{6}$/i.test(merged.theme[key]))throw Error('Invalid theme');
 for(const [key,options] of Object.entries({body:['Inter','Arial','Verdana'],heading:['Lora','Georgia','Inter'],hand:['Kalam','Caveat','Patrick Hand','Dancing Script','Sacramento'],coverage:['accents','headings','full']}))if(!options.includes(merged.theme[key]))merged.theme[key]=d.theme[key];
 merged.theme.night=!!merged.theme.night;merged.theme.calm=!!merged.theme.calm;merged.name=typeof raw.name==='string'?raw.name:d.name;merged.currency=['USD','EUR','GBP','CAD','AUD','TRY'].includes(raw.currency)?raw.currency:'USD';
 merged.suggestions=Array.isArray(raw.suggestions)&&raw.suggestions.every(x=>typeof x==='string')?raw.suggestions:d.suggestions;
 if(!Number.isFinite(merged.timer.remaining)||merged.timer.remaining<0||merged.timer.remaining>86400||merged.timer.end!==null&&!Number.isFinite(merged.timer.end))merged.timer=d.timer;
 return merged;}
let state=defaults(),storageError=false;try{const raw=localStorage.getItem(KEY);if(raw){try{state=merge(JSON.parse(raw));}catch(e){storageError=true;try{localStorage.setItem(KEY+'-recovery-'+Date.now(),raw);}catch{}}}}catch(e){storageError=true;}
let view='Dashboard',selectedDate=localDate(),calendarMonth=localDate().slice(0,7),filter='all',printSettings={size:'A4',layout:'pages',ink:true,blank:false,month:localDate().slice(0,7),sections:['Today','Task Planner','Brain Dump'],card:'Today'},timerHandle,installPrompt;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Saved in this browser';}catch(e){$('#save-status').textContent='Saving unavailable - download a backup';toast('Browser storage is unavailable. Download a backup to keep your work.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function day(date=selectedDate){return state.days[date]||{energy:'Normal',priorities:[],mood:''};}function setDay(patch,date=selectedDate){state.days[date]={...day(date),...patch};save();}
function records(mod){return state.records.filter(r=>r.module===mod);}
function button(text,action,attrs='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function nav(name){if($('#dialog').open)$('#dialog').close();view=name;filter='all';document.body.classList.remove('nav-open');$('#search-results').hidden=true;$('#search').value='';render();window.scrollTo(0,0);}
function luminance(hex){const n=hex.replace('#','');if(!/^[\da-f]{6}$/i.test(n))return 0;const c=[0,2,4].map(i=>parseInt(n.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2];}
function applyTheme(){const t=state.theme,root=document.documentElement.style;const bg=t.night?'#0c0b0e':t.bg,light=luminance(bg)>.38;root.setProperty('--main',t.main);root.setProperty('--accent',t.accent);root.setProperty('--bg',bg);root.setProperty('--panel',light?'#fffaf4':'#151216');root.setProperty('--text',light?'#241e25':'#f6f0e8');root.setProperty('--muted',light?'#655b68':'#b5aebb');root.setProperty('--line',light?'#d4c6cf':'#302730');root.setProperty('--button-ink',luminance(t.main)>.35?'#140c05':'#fff');root.setProperty('--body',`'${t.body}',Arial,sans-serif`);root.setProperty('--heading',`'${t.heading}',Georgia,serif`);root.setProperty('--hand',`'${t.hand}',cursive`);document.body.classList.toggle('hand-headings',t.coverage==='headings');document.body.classList.toggle('hand-full',t.coverage==='full');document.body.classList.toggle('calm',t.calm);$('meta[name=theme-color]').content=bg;}
function renderShell(){const extra=[['Theme Studio','◈'],['Print / PDF Center','▧'],['Sticker Shelf','✧'],['Settings & Backup','⚙']];$('#sidebar').innerHTML=`<div class="brand-title"><span class="pumpkin pumpkin-sprite" role="img" aria-label="Pumpkin"><img src="assets__reference.webp" alt=""></span><div><em>Halloween</em><strong>ADHD PLANNER</strong></div></div><div class="tagline">PLAN • FOCUS • ENJOY</div><div class="seasonline">A SPOOKY SEASON YOU CAN HANDLE</div><nav aria-label="Main navigation">${modules.map(([n,i])=>button(`<span class="ico" aria-hidden="true">${icon(navIcons[modules.findIndex(x=>x[0]===n)]||'spark')}</span>${n}`,'nav',`data-view="${n}" ${view===n?'aria-current="page"':''}`,view===n?'active':'')).join('')}</nav><div class="sidebar-end"><span style="font-size:36px">👻</span><span>A CALMER BRAIN<br>A SPOOKIER SEASON<br>A HAPPIER YOU</span></div><div class="brand-fixed"><img src="assets__logo.svg" alt="AurelyStudio logo"><div>AurelyStudio<small>Halloween ADHD Planner</small></div></div><nav class="extra-nav" aria-label="App tools">${extra.map(([n,i])=>button(`<span class="ico">${icon({'Theme Studio':'spark','Print / PDF Center':'note','Sticker Shelf':'gift','Settings & Backup':'list'}[n])}</span>${n}`,'nav',`data-view="${n}"`,view===n?'active':'')).join('')}</nav>`;$('#profile-name').textContent=state.name;$('#mobile-title').textContent=view;}
function countdown(){const now=new Date(),year=now.getMonth()>9?now.getFullYear()+1:now.getFullYear();return {days:Math.round((Date.UTC(year,9,31)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000),year};}
function tasksMarkup(date=localDate()){const ids=day(date).priorities;const rows=ids.map(id=>state.records.find(r=>r.id===id)).filter(Boolean).slice(0,3);return Array.from({length:3},(_,i)=>rows[i]?`<label class="taskcheck"><input type="checkbox" data-toggle="${rows[i].id}" ${rows[i].done?'checked':''}><span>${esc(rows[i].title)}</span></label>`:`<label class="taskcheck"><input type="checkbox" disabled><span>${button('Choose a small thing','choose-priority',`data-date="${date}"`,'link-button')}</span></label>`).join('');}
const tone=['#302534','#3b2326','#263124','#2c243b','#422717'];
const cats=[['Tasks','Task Planner','#fb8846'],['Decorations','Decorations','#a783d0'],['Shopping','Shopping List','#748299'],['Self-Care','Self-Care','#8ab275'],['Spooky Fun','Movie Nights','#f27779']];
function dashboard(){const c=countdown(),eligible=state.records.filter(r=>cats.some(x=>x[1]===r.module)),done=eligible.filter(r=>r.done).length,pct=eligible.length?Math.round(done/eligible.length*100):0;
const weekStart=new Date();weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const week=Array.from({length:5},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);const date=localDate(d),rr=state.records.filter(r=>r.date===date);return button(`<small>${d.toLocaleDateString('en-US',{weekday:'short'})}</small><strong>${d.getDate()}</strong><span class="day-state">${d.getMonth()===9&&d.getDate()===31?'🎃':rr.length&&rr.every(r=>r.done)?'✓':'·'}</span>`,'date',`data-date="${date}"`,'day-tile '+(date===localDate()?'today':''));}).join('');
const upcoming=state.records.filter(r=>!r.done&&r.date>=localDate()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);
return `<section class="hero" aria-label="Make This Halloween Yours"><img class="source" src="assets__reference.webp" alt="Friendly ghost holding a Spooky But Productive mug beside a black cat, pumpkins and candles. Make This Halloween Yours. A fun, focused and ADHD-friendly planner to help you enjoy the spooky season without the stress. Progress looks different for every brain, and that's okay. Small Steps, Spooky Progress, Same You."><div class="mobile-hero-copy"><h1>Make This<br>Halloween Yours</h1><p>A fun, focused and ADHD-friendly planner<br>for a spooky season you can enjoy.</p></div><span class="mobile-hero-hand">Small Steps<br>Spooky Progress<br>Same You ♡</span>${button('Plan Today　→','plan-today','data-view="Today"','hero-action plan')}${button('▣　View October Calendar','october','','hero-action calendar-action')}</section><div class="dashboard-grid"><section class="card countdown"><h2><span class="count-pumpkin-sprite" aria-hidden="true"><img src="assets__reference.webp" alt=""></span>Halloween Countdown</h2><span class="bat one">${batArt()}</span><div class="count-number">${c.days}</div><div class="days">DAYS LEFT</div><span class="bat two">${batArt()}</span>${button('→','nav','data-view="Halloween Countdown" aria-label="Open Halloween countdown"','circle-link')}</section><section class="card priorities"><h2>📋 Today: 3 Things Only</h2>${button('Reset','reset-priorities',`data-date="${localDate()}"`,'link-button reset')}${tasksMarkup()}</section><section class="card energy"><h2>🕯 How's your energy today?</h2><div class="energy-options">${['Low Energy','Normal','Locked In'].map((e,i)=>button(`<span class="battery" style="color:${['#eee','#ffc56c','#b3d594'][i]}">${icon('battery')}<i style="width:${[10,17,23][i]}px"></i></span>${e}<small>${['(Keep it tiny)','(Good to go)','(Let’s do this!)'][i]}</small>`,'energy',`data-energy="${e}" aria-pressed="${day(localDate()).energy===e}"`,day(localDate()).energy===e?'selected':'')).join('')}</div></section><section class="card progress-card"><h2>Your Progress</h2><div class="progress-content"><div class="ring" style="--sweep:${pct*3.6}deg" role="img" aria-label="${pct}% complete, ${done} of ${eligible.length} items"><strong>${pct}%</strong><span class="ghost">${ghostArt()}</span></div><div class="legend">${cats.map(([n,m,col])=>button(`<span class="dot" style="background:${col}"></span>${n}`,'nav',`data-view="${m}"`)).join('')}</div></div></section><section class="card quick-card"><h2>Quick Actions</h2><div class="quick-grid">${[['Add Task','☑','add','#24313a','Task Planner'],['New Note','♧','add','#283821','Brain Dump'],['Add to List','☷','add','#3c294c','Shopping List'],['Timer','♙','nav','#422728','Focus Tools'],['Brain Dump','♧','nav','#4a3420','Brain Dump'],['Mood Check','☺','mood','#3d3433',''],['Random Task','⚒','random','#333d22',''],['Treat Yourself','♧','treat','#402956','']].map(([n,i,a,t,m])=>button(`<span class="quick-icon" style="--tone:${t}">${icon({'Add Task':'check','New Note':'note','Add to List':'list','Timer':'timer','Brain Dump':'note','Mood Check':'smile','Random Task':'spark','Treat Yourself':'gift'}[n])}</span>${n}`,a,`data-module="${m}" data-view="${m}"`)).join('')}</div></section><section class="card dopamine"><h2>🪄 Spooky Dopamine Menu</h2>${state.suggestions.slice(0,5).map((s,i)=>button(`${['♙','🎃','✿','👻','◴'][i]}　${esc(s)}`,'suggestion',`data-index="${i}" style="--tone:${tone[i]}"`,'dopamine-row')).join('')}${button('See more →','nav','data-view="Spooky Dopamine Menu"','link-button see-more')}</section></div><div class="banner-row"><section class="magic-banner"><img src="assets__reference.webp" alt="Haunted house, bats and graveyard under a purple evening sky. Different Brain. Same Magic. Plan in a way that works for you.">${button('You Got This ♡','nav','data-view="Overwhelmed Mode"')}</section><section class="card tip"><h2>💡 Today's Spooky Tip</h2><p>You don't have to do everything. Choose one small thing and let that be enough.</p><span class="ghost">${ghostArt()}</span></section></div><div class="bottom-row"><section class="card"><h2>This Week</h2><div class="week">${week}</div></section><section class="card"><h2>Upcoming</h2><div class="upcoming-list">${upcoming.length?upcoming.map(r=>button(`🎃 <span>${esc(r.title)} <small>(${pretty(r.date)})</small></span>`,'edit',`data-id="${r.id}"`)).join(''):'<p class="muted">Your next plans will appear here.</p>'+button('Add a seasonal plan →','add','data-module="Party Planner"','link-button')}</div></section><section class="card moon-card"><span class="moon">☾</span><p>A More Magical<br>October<br>Is Possible</p><span class="bats">${batArt()} ${batArt()}</span></section></div>`;}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;}
function row(r){return `<article class="record ${r.done?'done':''}"><input type="checkbox" aria-label="Mark ${esc(r.title)} complete" data-toggle="${r.id}" ${r.done?'checked':''}><div class="record-body"><strong>${esc(r.title)}</strong><small>${pretty(r.date)}${r.detail?' · '+esc(r.detail):''}</small>${r.notes?`<small>${esc(r.notes)}</small>`:''}${r.module==='Budget'?`<span class="money">Planned ${money(r.planned)} · Actual ${money(r.actual)}</span>`:''}</div><div class="record-buttons">${button('Edit','edit',`data-id="${r.id}"`)}${button('Delete','delete',`data-id="${r.id}"`)}</div></article>`;}
function money(v){try{return new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency}).format(Number(v)||0);}catch{return String(v);}}
function listPage(mod){if(mod==='Budget')return budgetPage();let rr=records(mod).filter(r=>filter==='all'||(filter==='done'?r.done:!r.done));let extra='';if(mod==='Budget'){const all=records('Budget'),planned=all.reduce((n,r)=>n+(+r.planned||0),0),actual=all.reduce((n,r)=>n+(+r.actual||0),0);extra=`<div class="three-col" style="margin-bottom:20px">${[['Planned',planned],['Actual',actual],['Remaining',planned-actual]].map(([n,v])=>`<section class="card"><h2>${n}</h2><p class="metric money">${money(v)}</p><small>All saved budget entries</small></section>`).join('')}</div>`;}if(mod==='Spooky Dopamine Menu')extra=`<section class="card" style="margin-bottom:20px"><h2>Your dashboard suggestions</h2>${state.suggestions.map((s,i)=>button(esc(s)+' ✎','suggestion',`data-index="${i}" style="--tone:${tone[i%5]}"`,'dopamine-row')).join('')}</section>`;
return pageHead(mod,hints[mod],button('＋ Add '+(mod==='Brain Dump'?'note':'entry'),'add',`data-module="${mod}"`,'primary'))+sectionStudio(mod)+(mod==='Task Planner'?'':inspirationGallery(mod))+extra+`<div class="toolbar"><label>Show <select id="record-filter"><option value="all" ${filter==='all'?'selected':''}>All entries</option><option value="open" ${filter==='open'?'selected':''}>To do</option><option value="done" ${filter==='done'?'selected':''}>Completed</option></select></label><span class="muted">${rr.length} entries · full history</span></div><div class="records">${rr.length?rr.sort((a,b)=>a.date.localeCompare(b.date)).map(row).join(''):`<div class="empty"><span>✧</span>There is room for your first ${mod==='Brain Dump'?'thought':'plan'}.<br>Use Add ${mod==='Brain Dump'?'note':'entry'} to begin.</div>`}</div>`;}
function todayPage(){const rr=state.records.filter(r=>r.date===selectedDate);return pageHead('Today','Three things are enough. Keep the rest for another moment.',button('＋ Add task','add','data-module="Task Planner"','primary'))+`<div class="toolbar">${button('←','day-back','aria-label="Previous day"')}<input id="day-date" type="date" value="${selectedDate}" aria-label="Planner date">${button('→','day-next','aria-label="Next day"')}${button('Today','today-date')}</div><div class="two-col"><section class="card"><h2>3 Things Only · ${pretty(selectedDate)}</h2>${tasksMarkup(selectedDate)}<div class="actions" style="margin-top:20px">${button('Choose priorities','choose-priority',`data-date="${selectedDate}"`)}${button('Reset selection','reset-priorities',`data-date="${selectedDate}"`,'link-button')}</div></section><section class="card"><h2>A little check-in</h2><p>Energy: ${esc(day().energy)}</p><p>Mood: ${esc(day().mood||'Not checked in yet')}</p><div class="actions" style="margin-top:15px">${button('Mood check','mood')}${button('Start a 5-minute focus','nav','data-view="Focus Tools"')}</div><p class="hand" style="margin-top:20px">Small steps. Spooky progress. Same you.</p></section></div><h2 style="margin:25px 0 15px">Everything on this date</h2><div class="records">${rr.length?rr.map(row).join(''):'<div class="empty">No dated entries yet. Your history stays here as the calendar moves on.</div>'}</div>`;}
function calendar(){const [y,m]=calendarMonth.split('-').map(Number),start=new Date(y,m-1,1),offset=(start.getDay()+6)%7;return pageHead('October Calendar','Your whole year is here, too. Navigate any month and keep every memory.',button('＋ Add event','add','data-module="Party Planner"','primary'))+`<div class="toolbar">${button('← Previous','month-back')}<input id="calendar-month" type="month" value="${calendarMonth}" aria-label="Calendar month and year">${button('Next →','month-next')}${button('Today','calendar-today')}${button('October','october')}</div><section class="card"><h2>${start.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(y,m-1,1-offset+i),date=localDate(d),rr=state.records.filter(r=>r.date===date);return button(`<b>${d.getDate()}${d.getMonth()===9&&d.getDate()===31?' 🎃':''}</b>${rr.slice(0,2).map(r=>`<small>${r.done?'✓ ':''}${esc(r.title)}</small>`).join('')}${rr.length>2?`<small>+${rr.length-2} more</small>`:''}`,'date',`data-date="${date}" aria-label="${pretty(date)}, ${rr.length} entries"`,'calendar-day '+(d.getMonth()!==m-1?'outside ':'')+(date===localDate()?'selected':''));}).join('')}</div></section>`;}
function focus(overwhelmed=false){return pageHead(overwhelmed?'Overwhelmed Mode':'Focus Tools',overwhelmed?'Put the big list down for a moment. One gentle step is enough.':'A visible timer for a small, manageable session.')+`<section class="card focus-panel"><span style="font-size:45px">${overwhelmed?'👻':'🎃'}</span><p class="breathing">${overwhelmed?'Pause. Unclench your shoulders. Take a slow breath.':'A little focus, a little magic.'}</p>${overwhelmed?`<div class="actions">${button('Give me one small task','random','','primary')}${button('Choose something kind','treat')}</div>`:''}<div class="clock" id="clock">05:00</div><div class="actions">${[5,10,15,25].map(n=>button(n+' min','timer-set',`data-minutes="${n}"`)).join('')}</div><div class="actions" style="margin-top:16px">${button(state.timer.end?'Pause':'Start','timer-toggle','','primary')}${button('Reset','timer-reset')}</div><p class="muted" style="margin-top:20px">The timer keeps time while this app is in the background. Reopen it to see your progress.</p>${button('Back to Dashboard','nav','data-view="Dashboard"','link-button')}</section>`;}
function themePage(){const t=state.theme;const sel=(key,values)=>`<select data-theme="${key}">${values.map(v=>`<option ${t[key]===v?'selected':''}>${v}</option>`).join('')}</select>`;return pageHead('Theme Studio','Make your own cozy corner. Every choice saves in this browser.')+`<div class="theme-controls"><section class="card"><h2>Coordinated presets</h2><div class="actions">${['Candlelit','Moonlit Violet','Forest Night','Pumpkin Cream'].map((p,i)=>button(p,'preset',`data-preset="${i}"`)).join('')}</div></section><section class="card"><h2>Your colors</h2><div class="color-grid">${[['main','Main color'],['accent','Accent color'],['bg','Background']].map(([k,n])=>`<label>${n}<input type="color" data-theme="${k}" value="${t[k]}"><input aria-label="${n} HEX" data-hex="${k}" value="${t[k]}" pattern="#[0-9a-fA-F]{6}"></label>`).join('')}</div></section><div class="two-col"><section class="card"><h2>Typography</h2><div class="theme-controls"><label>Interface font${sel('body',['Inter','Arial','Verdana'])}</label><label>Heading font${sel('heading',['Lora','Georgia','Inter'])}</label><label>Handwriting accent${sel('hand',['Kalam','Caveat','Patrick Hand','Dancing Script','Sacramento'])}</label><label>Handwriting coverage<select data-theme="coverage">${[['accents','Accents'],['headings','Headings'],['full','Full Look']].map(([v,n])=>`<option value="${v}" ${t.coverage===v?'selected':''}>${n}</option>`).join('')}</select></label><small>Forms, dates and money always use a readable data font.</small></div></section><section class="card"><h2>Live preview</h2><div class="live-preview"><h2>Your little plan</h2><p class="metric numeric">3 <small>small things</small></p><p class="numeric">1 moment for you</p><p class="hand">Different brain. Same magic.</p>${button('Try a little encouragement','encourage','','primary')}</div><div style="display:grid;gap:15px;margin-top:22px"><label class="check-label"><input type="checkbox" data-theme="night" ${t.night?'checked':''}> Night Mode</label><label class="check-label"><input type="checkbox" data-theme="calm" ${t.calm?'checked':''}> Extra Calm Mode</label></div></section></div></div>`;}
function settings(){return pageHead('Settings & Backup','Keep your plans safe and move them between your own devices.')+`<div class="two-col"><section class="card"><h2>Your profile</h2><p>${esc(state.name)}</p>${button('Edit name','profile')}<label style="margin-top:18px">Currency<select id="currency">${['USD','EUR','GBP','CAD','AUD','TRY'].map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select></label><p class="instructions">Currency changes labels only. Existing amounts are not converted.</p></section><section class="card"><h2>Portable backup</h2><div class="actions">${button('Download backup','backup','','primary')}${button('Share backup','share-backup')}</div><label style="margin-top:20px">Restore a backup<input id="restore" type="file" accept="application/json,.json"></label><p class="instructions">Download → send to your other device → restore there. This includes your dated history, profile and themes. Clearing browser data can remove your plans. Back up regularly.</p></section><section class="card"><h2>Install your planner</h2>${button('Install app','install')}<p class="instructions">Installation is available over HTTPS or localhost. You can also open index.html directly for local planning.</p></section><section class="card"><h2>A fresh start</h2><p class="instructions">Try a small Halloween example, or clear your records. Download a backup first if you want to keep them.</p><div class="actions">${button('Add sample plans','sample')}${button('Clear planner data','clear-data')}</div></section></div>`;}
function printBrand(){return `<div class="print-brand"><img src="assets__logo.svg" alt="AurelyStudio"><div><b>AurelyStudio</b><small>Halloween ADHD Planner</small></div></div>`;}
function printedCalendar(){const ps=printSettings,[y,m]=ps.month.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7;return `<section class="print-section">${printBrand()}<h1>Month at a Glance</h1><p class="print-note">${ps.blank?'Month: __________________ Year: __________':new Date(y,m-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</p><div class="print-calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<b>${d}</b>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(y,m-1,1-offset+i),date=localDate(d),rr=state.records.filter(r=>r.date===date);return `<div>${ps.blank?'':`<strong>${d.getDate()}</strong>${rr.map(r=>`<p>${esc(r.title)}</p>`).join('')}`}</div>`;}).join('')}</div><h2>Little things to look forward to</h2><div class="writing-line"></div><div class="writing-line"></div><p class="print-note" style="margin-top:20px">Small steps. Spooky progress. · © AurelyStudio</p></section>`;}
function printContent(){const ps=printSettings,month=ps.month;let content='';if(ps.layout==='cards'){content=printCards(ps);}else content=ps.sections.map(section=>{if(section==='October Calendar')return printedCalendar();const rr=ps.blank?[]:(section==='Today'?day(selectedDate).priorities.map(id=>state.records.find(r=>r.id===id)).filter(Boolean):records(section).filter(r=>r.date.startsWith(month)));return `<section class="print-section">${printBrand()}<h1>${esc(section==='Today'?'Today: 3 Things Only':section)}</h1><p class="print-note">${ps.blank?'Date: __________________':section==='Today'?pretty(selectedDate):month} · Make this Halloween yours</p>${section==='Brain Dump'?`<p style="margin-top:20px">Let the thoughts land here.</p>${rr.map(r=>`<h3>${esc(r.title)}</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(r.notes)}</p>`).join('')}${Array.from({length:12},()=>'<div class="writing-line"></div>').join('')}`:`<h2>${section==='Today'?'Just the next three things':'Your seasonal plans'}</h2><table><thead><tr><th style="width:7%">✓</th><th>${section==='Budget'?'Item':'Plan / notes'}</th><th style="width:24%">${section==='Budget'?'Planned / Actual':'Date'}</th></tr></thead><tbody>${rr.map(r=>`<tr><td>${r.done?'✓':'□'}</td><td>${esc(r.title)}${r.detail?'\n'+esc(r.detail):''}${r.notes?'\n'+esc(r.notes):''}</td><td>${section==='Budget'?esc(money(r.planned)+' / '+money(r.actual)):esc(r.date)}</td></tr>`).join('')}${Array.from({length:Math.max(0,(section==='Today'?3:8)-rr.length)},()=>'<tr><td>□</td><td style="height:42px"></td><td></td></tr>').join('')}</tbody></table><h2>${section==='Today'?'One kind thing for myself':'Little notes for later'}</h2>${Array.from({length:section==='Today'?5:3},()=>'<div class="writing-line"></div>').join('')}`}<p class="print-note" style="margin-top:22px">Different Brain. Same Magic. · ${ps.blank?'Reusable blank page':`Snapshot ${new Date().toLocaleString('en-US')}`} · © AurelyStudio</p></section>`;}).join('');return `<div class="paper paper-${ps.size} ${ps.ink?'ink':''} ${ps.size==='Card'?'card-direct':''}">${content}</div>`;}
function setPaper(){const ps=printSettings,size=ps.size==='Card'?'100mm 150mm':ps.size==='Letter'?'letter':ps.size;$('#paper-style').textContent=`@page{size:${size};margin:${ps.size==='Card'?'0':'12mm'}}`;$('#print-root').innerHTML=view==='Budget'?budgetReport():printContent();}
function printPage(){const ps=printSettings;setPaper();return pageHead('Print / PDF Center','Pages for your desk. Little cards for wherever you need them.',button('Print / Save as PDF','print','','primary'))+`<section class="card"><div class="print-controls"><label>Paper size<select id="print-size">${[['A4','A4 · 210 × 297 mm'],['Letter','US Letter · 8.5 × 11 in'],['A5','A5 · 148 × 210 mm'],['Card','Card · 10 × 15 cm']].map(([v,n])=>`<option value="${v}" ${ps.size===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Layout<select id="print-layout"><option value="pages" ${ps.layout==='pages'?'selected':''}>Planner pages</option><option value="cards" ${ps.layout==='cards'?'selected':''}>Cut-out card · 10 × 15 cm</option></select></label><label>Records month<input id="print-month" type="month" value="${ps.month}"></label></div><div class="actions" style="margin-top:18px"><label class="check-label"><input id="print-ink" type="checkbox" ${ps.ink?'checked':''}> Ink saver</label><label class="check-label"><input id="print-blank" type="checkbox" ${ps.blank?'checked':''}> Blank writing pages</label></div>${ps.layout==='pages'?`<div class="section-checks">${['Today','October Calendar',...recordModules.filter(x=>x!=='Spooky Dopamine Menu')].map(n=>`<label><input type="checkbox" data-print-section="${n}" ${ps.sections.includes(n)?'checked':''}> ${n}</label>`).join('')}</div>`:`<label style="margin-top:18px">Card content<select id="print-card">${['Today','Task Planner','Self-Care','Shopping List'].map(n=>`<option ${ps.card===n?'selected':''}>${n}</option>`).join('')}</select></label>`}<p class="instructions">Choose your printer or Save as PDF in the browser dialog. Use 100% / Actual size, matching paper size, and turn off browser headers and footers. For color pages enable background graphics. Cards include cut lines on A4, US Letter and A5; choose Card for direct 10 × 15 cm printing. Printer support and dialog wording vary.</p></section><section class="card" style="margin-top:20px"><h2>Ready-to-print blank PDFs</h2><div class="actions">${[['A4','A4'],['US Letter','Letter'],['A5','A5'],['10 × 15 cm card','Card_10x15cm'],['Card on A4','Cutout_Card_A4'],['Card on US Letter','Cutout_Card_Letter']].map(([label,file])=>`<a class="pdf-download" href="PDF__AurelyStudio_Halloween_${file}.pdf" download>${label} ↓</a>`).join('')}</div></section><div class="print-preview-wrap" aria-label="Print preview">${printContent()}</div>`;}
function stickers(){return pageHead('Sticker Shelf','Six little reminders. Download transparent PNG stickers for your own planner pages.')+`<div class="sticker-grid">${['one-small-step','spooky-progress','rest-is-allowed','today-top-three','done-is-magic','treat-yourself'].map(n=>`<a href="assets__stickers__${n}.png" download><img src="assets__stickers__${n}.svg" alt="${n.replaceAll('-',' ')}"><br>Download sticker ↓</a>`).join('')}</div>`;}
function render(){applyTheme();renderShell();$('#main').innerHTML=view==='Dashboard'?dashboard():view==='Today'?todayPage():view==='October Calendar'?calendar():view==='Theme Studio'?themePage():view==='Settings & Backup'?settings():view==='Print / PDF Center'?printPage():view==='Sticker Shelf'?stickers():view==='Focus Tools'||view==='Overwhelmed Mode'?focus(view==='Overwhelmed Mode'):view==='Halloween Countdown'?pageHead('Halloween Countdown','A little room to plan. A lot of room to enjoy.')+`<section class="card focus-panel"><span style="font-size:55px">🎃</span><div class="clock">${countdown().days}</div><h2>days until October 31, ${countdown().year}</h2><p class="hand" style="margin:25px">Your season. Your pace.</p><div class="actions">${button('Plan a milestone','add','data-module="Task Planner"','primary')}${button('View October','october')}</div></section>`:listPage(view);if(['Dashboard','Today','Task Planner','Budget','Focus Tools','Overwhelmed Mode','October Calendar','Halloween Countdown'].includes(view))$('#main').insertAdjacentHTML('beforeend',supplementalGallery(view));tick();}
function showDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button('×','close','aria-label="Close dialog"')}</div>${body}`;d.querySelectorAll('form').forEach(f=>f.noValidate=true);if(!d.open)d.showModal();}
function entryForm(mod,id){const r=id?state.records.find(r=>r.id===id):null;mod=r?.module||mod||'Task Planner';const fieldLabels={'Costume Planner':'Pieces / size / shop','Shopping List':'Quantity / shop','Decorations':'Room / supplies','Party Planner':'Location / guests','Trick or Treat':'Route / candy / start time','Meal & Treats':'Ingredients / servings','Movie Nights':'Where to watch / snacks','Self-Care':'How much time / what helps','After Halloween':'Keep / donate / store'};showDialog(r?'Edit '+mod:'Add to '+mod,`<form id="entry-form" data-id="${id||''}" data-module="${mod}"><label>${mod==='Brain Dump'?'Thought':'Title'}<input name="title" value="${esc(r?.title||'')}" required maxlength="180" autofocus></label><div class="form-row"><label>Date<input name="date" type="date" value="${r?.date||selectedDate}" required></label><label>${fieldLabels[mod]||'Details'}<input name="detail" value="${esc(r?.detail||'')}" maxlength="300"></label></div>${mod==='Budget'?`<label>Category<select name="category">${budgetCategories.map(c=>`<option ${c===(r?.category||'Other')?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-row"><label>Planned (${state.currency})<input name="planned" type="number" min="0" step="0.01" max="999999999.99" value="${r?.planned||0}" required></label><label>Actual (${state.currency})<input name="actual" type="number" min="0" step="0.01" max="999999999.99" value="${r?.actual||0}" required></label></div><div class="budget-form-live" id="budget-draft" aria-live="polite"></div><p class="budget-form-error" id="budget-form-error" role="alert"></p>`:''}<label>${mod==='Meal & Treats'?'Recipe / preparation':mod==='Brain Dump'?'Let it all out':'Notes / next small step'}<textarea name="notes" maxlength="12000">${esc(r?.notes||'')}</textarea></label><div class="actions"><button class="primary" type="submit">Save ${r?'changes':'entry'}</button>${button('Cancel','close')}</div></form>`);if(mod==='Budget')updateBudgetDraft();}
function editSuggestion(i){showDialog('Your spooky pick-me-up',`<form id="suggestion-form" data-index="${i}"><label>Suggestion<input name="text" value="${esc(state.suggestions[i])}" required maxlength="150"></label><div class="actions"><button type="submit" class="primary">Save suggestion</button>${button('Add to my plans','suggestion-add',`data-index="${i}"`)}</div></form>`);}
function backupFile(){return new File([JSON.stringify(state,null,2)],`AurelyStudio-Halloween-backup-${localDate()}.json`,{type:'application/json'});}function download(file){const a=document.createElement('a'),u=URL.createObjectURL(file);a.href=u;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
async function restore(file){let restored;try{restored=merge(JSON.parse(await file.text()));}catch{toast('This backup could not be read. Your current data is unchanged.');return;}if(!confirm('Replace the data in this browser with this backup? Download a backup first if needed.'))return;state=restored;save();render();toast('Your backup is restored.');}

function sample(){const year=countdown().year;const samples=[['Task Planner','Plan my costume',localDate()],['Decorations','Order decorations',`${year}-10-15`],['Movie Nights','Watch a Halloween movie',localDate()],['Costume Planner','Order costume',`${year}-10-10`],['Party Planner','Halloween party',`${year}-10-28`],['Trick or Treat','Trick or Treat!',`${year}-10-31`]];const created=samples.map(([module,title,date])=>({id:uid(),module,title,date,detail:'Sample plan - edit to make it yours',notes:'',done:false}));state.records.push(...created);setDay({priorities:created.slice(0,3).map(r=>r.id)},localDate());save();render();toast('Six sample plans added. You can edit or delete each one.');}
function tick(){const el=$('#clock');let rem=state.timer.end?Math.max(0,Math.ceil((state.timer.end-Date.now())/1000)):state.timer.remaining;if(state.timer.end&&rem===0){state.timer={remaining:0,end:null};save();toast('Your focus session is complete. Take a little pause.');if(view==='Focus Tools'||view==='Overwhelmed Mode')render();}if(el)el.textContent=String(Math.floor(rem/60)).padStart(2,'0')+':'+String(rem%60).padStart(2,'0');}
function choosePriorities(date){const rr=state.records.filter(r=>r.module==='Task Planner'||day(date).priorities.includes(r.id));showDialog('Choose up to 3 things',`<form id="priorities-form" data-date="${date}"><p class="muted">Choose the small steps you want to see on ${pretty(date)}.</p>${rr.map(r=>`<label class="check-label"><input name="priority" type="checkbox" value="${r.id}" ${day(date).priorities.includes(r.id)?'checked':''}>${esc(r.title)}</label>`).join('')||'<p>Add a task first to choose your daily priorities.</p>'}<div class="actions"><button type="submit" class="primary">Save priorities</button>${button('Add task','add','data-module="Task Planner"')}</div><p id="priority-error" role="alert"></p></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='plan-today'){selectedDate=localDate();nav('Today');}else if(a==='nav')nav(b.dataset.view);else if(a==='menu')document.body.classList.toggle('nav-open');else if(a==='close')$('#dialog').close();else if(a==='add')entryForm(b.dataset.module);else if(a==='edit'){const rec=state.records.find(r=>r.id===b.dataset.id);selectedDate=rec.date;entryForm(null,b.dataset.id);}else if(a==='delete'){const r=state.records.find(r=>r.id===b.dataset.id);if(confirm(`Delete “${r.title}”? This removes it from your saved history.`)){state.records=state.records.filter(x=>x.id!==r.id);for(const d of Object.values(state.days))d.priorities=d.priorities.filter(id=>id!==r.id);save();$('#dialog').close();render();toast('Entry deleted.');}}else if(a==='date'){selectedDate=b.dataset.date;nav('Today');}else if(a==='october'){calendarMonth=`${countdown().year}-10`;nav('October Calendar');}else if(a==='energy'){setDay({energy:b.dataset.energy},localDate());render();toast('Energy check-in saved.');}else if(a==='reset-priorities'){setDay({priorities:[]},b.dataset.date);render();toast('Priority selection cleared. Your tasks are still saved.');}else if(a==='choose-priority')choosePriorities(b.dataset.date);else if(a==='profile'){showDialog('Make yourself at home',`<form id="profile-form"><label>What should we call you?<input name="name" value="${esc(state.name)}" maxlength="40" required></label><small>Your name stays in this browser. No account needed.</small><button type="submit" class="primary">Save name</button></form>`);}else if(a==='mood'){showDialog('A little mood check',`<form id="mood-form" data-date="${view==='Today'?selectedDate:localDate()}"><label>How are you feeling?<select name="mood">${['Cozy','Excited','Tired','Scattered','Content','Need a pause'].map(n=>`<option ${day(view==='Today'?selectedDate:localDate()).mood===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Energy<select name="energy">${['Low Energy','Normal','Locked In'].map(n=>`<option ${day(view==='Today'?selectedDate:localDate()).energy===n?'selected':''}>${n}</option>`).join('')}</select></label><button type="submit" class="primary">Save check-in</button></form>`);}else if(a==='random'){const rr=state.records.filter(r=>!r.done&&r.module==='Task Planner');if(rr.length){const r=rr[Math.floor(Math.random()*rr.length)];showDialog('Just one small step',`<p class="hand">${esc(r.title)}</p><p style="margin:15px 0">${esc(r.notes||'Give it five minutes. Then decide what feels right.')}</p><div class="actions">${button('Open task','edit',`data-id="${r.id}"`,'primary')}${button('Start timer','timer-from-dialog')}</div>`);}else{toast('Add a task first - then let us pick a small step.');entryForm('Task Planner');}}else if(a==='treat'){showDialog('A little moment for you',`<p class="hand">${esc(state.suggestions[Math.floor(Math.random()*state.suggestions.length)]||'Take a small, quiet break.')}</p><p class="instructions">You do not need to earn a moment of rest.</p>${button('Save a self-care plan','add','data-module="Self-Care"','primary')}`);}else if(a==='encourage')toast('You can begin with one tiny thing.');else if(a==='suggestion')editSuggestion(+b.dataset.index);else if(a==='suggestion-add'){const s=state.suggestions[+b.dataset.index];$('#dialog').close();entryForm('Spooky Dopamine Menu');$('#entry-form [name=title]').value=s;}else if(a==='notifications'){const rr=state.records.filter(r=>!r.done&&r.date>=localDate()).sort((a,b)=>a.date.localeCompare(b.date));showDialog('Your upcoming plans',`<div class="records">${rr.slice(0,12).map(r=>button(`${esc(r.title)} · ${pretty(r.date)}`,'edit',`data-id="${r.id}"`)).join('')||'<p>No upcoming plans yet. Add a dated entry to see it here.</p>'}</div><p class="instructions">These reminders appear inside your planner. They are not device push notifications.</p>`);}else if(['day-back','day-next'].includes(a)){const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+(a==='day-next'?1:-1));selectedDate=localDate(d);render();}else if(a==='today-date'){selectedDate=localDate();render();}else if(['month-back','month-next'].includes(a)){const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=localDate(new Date(y,m-1+(a==='month-next'?1:-1),1)).slice(0,7);render();}else if(a==='calendar-today'){calendarMonth=localDate().slice(0,7);render();}else if(a==='preset'){const presets=[['#ff873e','#b992d8','#100e11'],['#c19cec','#e8ad6b','#15101f'],['#a9c383','#ffc47e','#101713'],['#a74518','#75548b','#faf2e6']];[state.theme.main,state.theme.accent,state.theme.bg]=presets[+b.dataset.preset];state.theme.night=false;save();render();}else if(a==='timer-set'){state.timer={remaining:+b.dataset.minutes*60,end:null};save();render();}else if(a==='timer-toggle'){if(state.timer.end)state.timer={remaining:Math.max(0,Math.ceil((state.timer.end-Date.now())/1000)),end:null};else{if(state.timer.remaining===0)state.timer.remaining=300;state.timer.end=Date.now()+state.timer.remaining*1000;}save();render();}else if(a==='timer-reset'){state.timer={remaining:300,end:null};save();render();}else if(a==='timer-from-dialog'){$('#dialog').close();nav('Focus Tools');}else if(a==='print'){if(printSettings.layout==='pages'&&!printSettings.sections.length){toast('Choose at least one section to print.');return;}setPaper();await document.fonts.ready;await Promise.all(Array.from($('#print-root').querySelectorAll('img')).map(i=>i.decode().catch(()=>{})));window.print();}else if(a==='backup')download(backupFile());else if(a==='share-backup'){const f=backupFile();if(navigator.canShare?.({files:[f]})){try{await navigator.share({files:[f],title:'Halloween Planner backup'});}catch(e){if(e.name!=='AbortError')download(f);}}else{download(f);toast('Backup downloaded. Send the file to your other device.');}}else if(a==='sample')sample();else if(a==='clear-data'){if(confirm('Clear all planner records and check-ins? This cannot be undone without a backup.')){state.records=[];state.days={};save();render();toast('Planner cleared. Your theme and profile are kept.');}}else if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else showDialog('Install your Halloween planner','<p>iPhone / iPad: open the hosted app in Safari → Share → Add to Home Screen.</p><p class="instructions">Android / desktop: open the hosted app, then browser menu → Install app / Add to Home screen. This requires HTTPS or localhost. Installation availability depends on your browser.</p>');}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='entry-form'){const id=f.dataset.id;const r={id:id||uid(),module:f.dataset.module,title:String(fd.get('title')).trim(),date:String(fd.get('date')),detail:String(fd.get('detail')||'').trim(),notes:String(fd.get('notes')||'').trim(),done:false};if(!r.title||!validDate(r.date)){toast('Enter a title and a valid date.');return;}if(r.module==='Budget'){r.planned=Number(fd.get('planned'));r.actual=Number(fd.get('actual'));r.category=String(fd.get('category')||'Other');if(!Number.isFinite(r.planned)||!Number.isFinite(r.actual)||r.planned<0||r.actual<0||r.planned>999999999.99||r.actual>999999999.99)return;r.planned=Math.round(r.planned*100)/100;r.actual=Math.round(r.actual*100)/100;}if(id){const i=state.records.findIndex(x=>x.id===id);r.done=state.records[i].done;state.records[i]=r;}else{state.records.push(r);if(r.module==='Task Planner'&&day(r.date).priorities.length<3)setDay({priorities:[...day(r.date).priorities,r.id]},r.date);}save();$('#dialog').close();render();toast('Entry saved.');}else if(f.id==='profile-form'){state.name=String(fd.get('name')).trim()||'Spooky Friend';save();$('#dialog').close();render();}else if(f.id==='mood-form'){setDay({mood:fd.get('mood'),energy:fd.get('energy')},f.dataset.date);$('#dialog').close();render();toast('Check-in saved.');}else if(f.id==='suggestion-form'){state.suggestions[+f.dataset.index]=String(fd.get('text')).trim();save();$('#dialog').close();render();}else if(f.id==='priorities-form'){const ids=fd.getAll('priority');if(ids.length>3){$('#priority-error').textContent='Choose no more than three things. The rest will still be here.';return;}setDay({priorities:ids},f.dataset.date);$('#dialog').close();render();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.toggle){const r=state.records.find(r=>r.id===t.dataset.toggle);r.done=t.checked;save();if(t.closest('dialog'))$('#dialog').close();render();}else if(t.dataset.theme){state.theme[t.dataset.theme]=t.type==='checkbox'?t.checked:t.value;save();applyTheme();}else if(t.dataset.hex){if(/^#[\da-f]{6}$/i.test(t.value)){state.theme[t.dataset.hex]=t.value;save();render();}else toast('Use a six-digit HEX color, such as #ff873e.');}else if(t.id==='record-filter'){filter=t.value;render();}else if(t.id==='day-date'&&t.value){selectedDate=t.value;render();}else if(t.id==='calendar-month'&&t.value){calendarMonth=t.value;render();}else if(t.id==='currency'){state.currency=t.value;save();}else if(t.id==='restore'){if(t.files[0])restore(t.files[0]);t.value='';}else if(t.id.startsWith('print-')||t.dataset.printSection){if(t.id==='print-size'){printSettings.size=t.value;if(t.value==='Card')printSettings.layout='cards';}if(t.id==='print-layout'){printSettings.layout=t.value;if(t.value==='pages'&&printSettings.size==='Card')printSettings.size='A4';}if(t.id==='print-month'&&t.value)printSettings.month=t.value;if(t.id==='print-ink')printSettings.ink=t.checked;if(t.id==='print-blank')printSettings.blank=t.checked;if(t.id==='print-card')printSettings.card=t.value;if(t.dataset.printSection){printSettings.sections=t.checked?[...printSettings.sections,t.dataset.printSection]:printSettings.sections.filter(x=>x!==t.dataset.printSection);}render();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.theme&&t.type==='color'){state.theme[t.dataset.theme]=t.value;const hex=$(`[data-hex="${t.dataset.theme}"]`);if(hex)hex.value=t.value;save();applyTheme();}});
$('#search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),box=$('#search-results');box.hidden=!q;if(!q)return;const rr=state.records.filter(r=>[r.title,r.notes,r.detail,r.module,r.date].join(' ').toLowerCase().includes(q));const mm=[...modules.map(x=>x[0]),'Theme Studio','Print / PDF Center','Settings & Backup'].filter(x=>x.toLowerCase().includes(q));box.innerHTML=mm.map(n=>button(n,'nav',`data-view="${n}"`)).join('')+rr.slice(0,25).map(r=>button(`${esc(r.title)}<small> · ${esc(r.module)} · ${r.date}</small>`,'edit',`data-id="${r.id}"`)).join('')||'<p style="padding:12px">No saved plans match this search.</p>';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('nav-open');$('#search-results').hidden=true;}});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#search-results').hidden=true;});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('beforeprint',setPaper);if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>toast('Offline installation is unavailable in this browser.'));
render();timerHandle=setInterval(tick,1000);let lastToday=localDate();setInterval(()=>{const next=localDate();if(next!==lastToday){if(selectedDate===lastToday)selectedDate=next;lastToday=next;render();}},30000);if(storageError){$('#save-status').textContent='Check storage — download a backup';toast('Saved data needs attention. A recovery copy was kept when browser storage allowed it.');}
